-- Frozen differential fixtures generated from real NumPy 2.3.5
local np=require("luaray_core")
assert(np._version=="0.100.0-dev")
local checks,cases=0,0
local function deep(a,b,desc)
    assert(type(a)==type(b),desc..': type mismatch: '..type(a)..' vs '..type(b))
    if type(a)=='table' then
        assert(#a==#b,desc..': length mismatch: '..#a..' vs '..#b)
        for i=1,#a do deep(a[i],b[i],desc..'['..i..']') end
    else
        assert(a==b,desc..': '..tostring(a)..' vs '..tostring(b))
    end
    checks=checks+1
end
do
local r=np.random.default_rng(9876)
local x=np.transpose(np.astype(np.arange(12,"int64"):reshape({3,4}),"int32"),{2,1})
local before=x:tolist()
local out=np.zeros({4,3},"int32")
local y=r:permuted(x,2,out)
deep(y.dtype,"int32","9876/(3, 4)/int32/transpose/1/out_new dtype")
deep(y:tolist(),{{0,4,8},{1,9,5},{2,10,6},{7,11,3}},"9876/(3, 4)/int32/transpose/1/out_new values")
deep(x:tolist(),{{0,4,8},{1,5,9},{2,6,10},{3,7,11}},"9876/(3, 4)/int32/transpose/1/out_new source")
assert(rawequal(y,out),"out must return identical ndarray")
deep(r:raw_hex(),"fa48e48c3b034932","9876/(3, 4)/int32/transpose/1/out_new pcg")
cases=cases+1; end
