local x=np.astype(np.arange(0,"int64"):reshape({0,4}),"int32")
local before=x:tolist()
local out=np.zeros({0,4},"int32")
local y=r:permuted(x,2,out)
deep(y.dtype,"int32","9876/(0, 4)/int32/plain/1/out_new dtype")
deep(y:tolist(),{},"9876/(0, 4)/int32/plain/1/out_new values")
deep(x:tolist(),{},"9876/(0, 4)/int32/plain/1/out_new source")
assert(rawequal(y,out),"out must return identical ndarray")
deep(r:raw_hex(),"b42062a2610530af","9876/(0, 4)/int32/plain/1/out_new pcg")
cases=cases+1; end
