local x=np.astype(np.arange(0,"int64"):reshape({2,0}),"int32")
local before=x:tolist()
local y=r:permuted(x,-1,x)
deep(y.dtype,"int32","9876/(2, 0)/int32/plain/-1/out_same dtype")
deep(y:tolist(),{{},{}},"9876/(2, 0)/int32/plain/-1/out_same values")
deep(x:tolist(),{{},{}},"9876/(2, 0)/int32/plain/-1/out_same source")
assert(rawequal(y,x),"out must return identical ndarray")
deep(r:raw_hex(),"b42062a2610530af","9876/(2, 0)/int32/plain/-1/out_same pcg")
cases=cases+1; end
